  if (language === 'C++' && !/^\s*#include/m.test(snippet)) return `#include <bits/stdc++.h>\nusing namespace std;\n\n${snippet}`;
  if (language === 'Python' && !/^\s*(from|import)\s/m.test(snippet)) return `from __future__ import annotations\nfrom typing import *\nfrom collections import *\nimport heapq, math, bisect, itertools, functools\n\n${snippet}`;
