function useSaved<T>(key: string, initial: T): [T, React.Dispatch<React.SetStateAction<T>>] {
  const [value, setValue] = useState<T>(() => { try { const raw = localStorage.getItem(`algomate:${key}`); return raw ? JSON.parse(raw) as T : initial; } catch { return initial; } });
  useEffect(() => { localStorage.setItem(`algomate:${key}`, JSON.stringify(value)); }, [key, value]);
  return [value, setValue];
}

